using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;
namespace FortsStudio {
 public partial class Preview {
  void Ground(Graphics g){if(!Project.Preview.RangeGrounded)return;var image=Assets.Image("environment/"+Project.Preview.Background+"/ground/ground1.dds",Project.GameRoot);foreach(var bounds in groundBounds){if(!bounds.Any)continue;var a=Screen(new PointF(bounds.Left-15/Unit,bounds.Y));var b=Screen(new PointF(bounds.Right+15/Unit,bounds.Y));if(!VisibleLine(a,b,55*zoom))continue;var rect=new RectangleF(a.X,a.Y,b.X-a.X,55*zoom);if(image!=null){using(var brush=new TextureBrush(image,WrapMode.Tile))using(var matrix=new Matrix()){matrix.Translate(camera.X,camera.Y);brush.Transform=matrix;g.FillRectangle(brush,rect);}}else using(var brush=new SolidBrush(Color.FromArgb(75,73,62)))g.FillRectangle(brush,rect);using(var pen=new Pen(Color.FromArgb(175,169,142),Math.Max(2,5*zoom)))g.DrawLine(pen,a,b);}}
  string PointKey(PointF p){return p.X.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+":"+p.Y.ToString("R",System.Globalization.CultureInfo.InvariantCulture);}
  void Joints(Graphics g){var one=Assets.Image("materials/node_team1.tga",Project.GameRoot);var two=Assets.Image("materials/node_team2.tga",Project.GameRoot);foreach(var node in sceneJoints){var pt=Screen(node.Point);var image=node.Team==1?one:node.Team==2?two:Assets.Image("materials/node_team"+node.Team+".tga",Project.GameRoot);if(image!=null){float w=image.Width*.5f*zoom,h=image.Height*.5f*zoom;if(!VisibleLine(pt,pt,Math.Max(w,h)/2))continue;g.DrawImage(image,pt.X-w/2,pt.Y-h/2,w,h);}else{float r=8*zoom;if(!VisibleLine(pt,pt,r))continue;g.FillEllipse(node.Team==2?Brushes.IndianRed:Brushes.SteelBlue,pt.X-r,pt.Y-r,2*r,2*r);g.DrawEllipse(Pens.Black,pt.X-r,pt.Y-r,2*r,2*r);}}}
  List<PointF[]> claddingFaces=new List<PointF[]>();
  void BuildCladding(){if(!claddingDirty)return;claddingDirty=false;claddingFaces.Clear();foreach(int team in new[]{1,2}){
   var points=new Dictionary<string,PointF>();var neighbors=new Dictionary<string,List<string>>();var attachments=new Dictionary<string,bool>();
   foreach(var beam in sceneBeams){if(beam.Team!=team||beam.Behind)continue;var a=new PointF(beam.X1,beam.Y1);var b=new PointF(beam.X2,beam.Y2);string ka=PointKey(a),kb=PointKey(b);if(ka==kb)continue;points[ka]=a;points[kb]=b;if(!neighbors.ContainsKey(ka))neighbors[ka]=new List<string>();if(!neighbors.ContainsKey(kb))neighbors[kb]=new List<string>();if(!neighbors[ka].Contains(kb))neighbors[ka].Add(kb);if(!neighbors[kb].Contains(ka))neighbors[kb].Add(ka);attachments[ka+"|"+kb]=beam.Attach;attachments[kb+"|"+ka]=beam.Attach;}
   foreach(var pair in neighbors){PointF p=points[pair.Key];pair.Value.Sort((a,b)=>Math.Atan2(points[a].Y-p.Y,points[a].X-p.X).CompareTo(Math.Atan2(points[b].Y-p.Y,points[b].X-p.X)));}
   var used=new HashSet<string>();foreach(string root in neighbors.Keys)foreach(string next in neighbors[root]){string a=root,b=next;var polygon=new List<PointF>();bool attach=false,closed=false;
    for(int step=0;step<=sceneBeams.Count*2;step++){string edge=a+"|"+b;if(!used.Add(edge))break;polygon.Add(points[a]);bool attachment;if(attachments.TryGetValue(edge,out attachment)&&attachment)attach=true;var options=neighbors[b];int index=options.IndexOf(a);string c=options[(index+options.Count-1)%options.Count];a=b;b=c;if(a==root&&b==next){closed=true;break;}}
    if(!closed||!attach||polygon.Count<3)continue;double area=0;for(int i=0;i<polygon.Count;i++){var p=polygon[i];var q=polygon[(i+1)%polygon.Count];area+=p.X*q.Y-q.X*p.Y;}if(area<=.001)continue;claddingFaces.Add(polygon.ToArray());
   }
  }}
  void Cladding(Graphics g){BuildCladding();var image=Assets.Image("materials/wood_panel.dds",Project.GameRoot);foreach(var polygon in claddingFaces){var screen=new PointF[polygon.Length];float left=Single.MaxValue,top=Single.MaxValue,right=Single.MinValue,bottom=Single.MinValue;for(int i=0;i<polygon.Length;i++){var point=Screen(polygon[i]);screen[i]=point;left=Math.Min(left,point.X);right=Math.Max(right,point.X);top=Math.Min(top,point.Y);bottom=Math.Max(bottom,point.Y);}if(right<0||left>ScenePaintWidth||bottom<0||top>ScenePaintHeight)continue;if(image!=null){using(var brush=new TextureBrush(image,WrapMode.Tile))using(var matrix=new Matrix()){matrix.Translate(camera.X,camera.Y);matrix.Scale(zoom*.5f,zoom*.5f);brush.Transform=matrix;g.FillPolygon(brush,screen);}}else using(var fill=new SolidBrush(Color.FromArgb(100,76,52)))g.FillPolygon(fill,screen);}}
 }
}
